.shared-page-deck>.shared-page-panel.is-active{position:relative;}
.shared-page-tabs{position:relative;isolation:isolate;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;padding:4px;border:1px solid var(--line,var(--color-border-subtle));border-radius:18px;background:var(--paper,var(--color-surface-panel));}
.shared-page-tabs::before{content:"";position:absolute;inset:4px auto 4px 4px;width:calc((100% - 8px)/2);border-radius:14px;background:var(--color-surface-raised,#e3e8d8);transform:translateX(calc(var(--page-index,0)*100%));transition:transform var(--ui-duration-page) var(--ui-easing-page);pointer-events:none;z-index:-1;}
